  "收到事件时比较指定的项目共享状态；状态键缺失或类型不同时不触发（包括不等于）。状态改变本身不触发转换。数字精确比较，不使用误差容限。": "Compare the specified project shared state when an event is received. A missing key or a different type never matches, including not equal. State changes alone do not trigger transitions. Numbers use exact comparison without a tolerance.",
