  "同一状态的同名事件按转换顺序检查，执行首个匹配分支；不匹配时继续。无条件分支只能位于该组最后。": "For the same state and event name, check transitions in order and run the first matching branch; continue past non-matches. An unconditional branch must be last in its group.",
  "同一状态的同名事件只能有一条转换；切回此模式会保留现有分支，请手动修正重复转换。": "Each state allows only one transition per event name. Switching back preserves existing branches; fix duplicate transitions manually.",
