  "Godot / 动画状态表": "Godot / Animation state table",
  "配置初始状态以及事件或自然完成转换，生成普通脚本。各状态的 clip_ 参数在行为编辑器中选入片段；运行时启动初始状态，共用当前场景播放头。生成后继续编辑普通源码。": "Configure an initial state and transitions on events or natural completion to generate an ordinary script. Assign each state’s clip_ parameter in the behavior editor. The initial state starts on ready and uses the current scene’s shared playhead. Continue editing the generated source as normal.",
  "动画状态与转换": "Animation states and transitions",
  "就绪时会启动初始状态，所有行为共享当前场景的动画播放头。请让一个行为负责状态切换。": "The initial state starts on ready. All behaviors share the current scene’s animation playhead. Use one behavior to control state transitions.",
  "保存后，在场景行为的 clip_状态标识 参数中选择动画片段；留空播放完整动画。生成后可编辑普通 TXT 源码，此表不会从源码逆向回填。": "After saving, assign animation clips to the scene behavior’s clip_<state key> parameters; leave them empty to play the full animation. The generated TXT source is editable. This table is not restored from edited source.",
