  "事件名以字母开头，只含字母、数字、点、下划线或连字符，最多 64 个字符。同一状态的同名事件或完成转换只能有一条。": "Event names start with a letter and contain only letters, numbers, dots, underscores or hyphens, up to 64 characters. Each state allows one transition per event name and one on completion.",
