  "丢弃本次动画表单修改？原文草稿不会改变。": "Discard these animation form changes? The source draft will remain unchanged.",
  "正在读取动画文档…": "Reading animation document…",
  "编辑关键帧，检查后应用到原文草稿。": "Edit keyframes, then check and apply to the source draft.",
  "无法读取有效动画文档，请检查原文。": "Could not read a valid animation document. Check the source.",
  "正在检查动画修改…": "Checking animation changes…",
  "动画修改已检查，请审阅完整原文后应用。": "Animation changes are checked. Review the complete source before applying.",
  "动画修改未通过检查，输入已保留。": "Animation checks failed. Your input is retained.",
  "正在应用动画修改到原文草稿…": "Applying animation changes to the source draft…",
  "动画修改未确认应用，输入已保留。": "Animation changes could not be confirmed as applied. Your input is retained.",
  "无法生成动画轨道编号，请重试。": "Could not generate an animation track ID. Try again.",
  "动画修改已应用到原文草稿；尚未保存。": "Animation changes applied to the source draft; not yet saved.",
  "动画修改已应用；文本与已保存版本一致。": "Animation changes applied; text matches the saved version.",
  "动画控制记录": "Animation command history",
  "只读显示动画命令执行时的状态和播放头，不代表当前画面。切换场景时保留记录，重新运行后清空。": "Read-only history of state and playhead position when animation commands executed, not the current frame. History persists across scenes and resets on a new run.",
  "按场景或动画标识筛选": "Filter scene or animation IDs",
  "正在打开动画控制来源…": "Opening animation command source…",
  "无法打开动画控制来源，请返回编辑器查找该文档。": "Could not open the animation command source. Find the document in the editor.",
  "命令序号 {0} · 显示 {1} / {2} 条动画命令": "Command sequence {0} · Showing {1} / {2} animation commands",
  "没有匹配的动画命令。": "No matching animation commands.",
  "当前没有已执行的动画命令。": "No animation commands have been executed yet.",
  "已执行暂停命令": "Pause command executed",
  "已执行跳转命令": "Seek command executed",
  "场景 {0} · 动画 {1}": "Scene {0} · Animation {1}",
  "执行后状态：{0} · 播放头 {1} 秒": "State after execution: {0} · Playhead {1} seconds",
  "动画声明：{0} · {1}": "Animation declaration: {0} · {1}",
  "打开动画声明": "Open animation declaration",
  "暂停": "Pause",
  "结束": "Finished",
  "命名动画片段": "Named animation clips",
  "添加动画片段": "Add animation clip",
  "片段复用现有轨道，只指定原时间轴的区间。行为按稳定编号选择；更名不会改变编号，删除后原引用将失效。": "Clips reuse existing tracks and select a range of the source timeline. Behaviors select stable IDs; renaming keeps the ID, while deletion invalidates its references.",
  "片段 {0} / 32": "Clips {0} / 32",
  "动画片段 {0}": "Animation clip {0}",
  "片段名称": "Clip name",
  "片段开始（秒）": "Clip start (seconds)",
  "片段结束（秒）": "Clip end (seconds)",
  "片段循环": "Loop clip",
  "移除动画片段": "Remove animation clip",
  "无法生成动画片段编号，请重试。": "Could not generate an animation clip ID. Try again.",
  "预览动画片段": "Preview animation clip",
  "按场景、动画或片段筛选": "Filter by scene, animation, or clip",
  "已执行选择片段命令": "Clip selection applied",
  "片段：{0} · {1} · 原时间轴 {2}–{3} 秒": "Clip: {0} · {1} · Source timeline {2}–{3} s",
  "打开动画片段声明": "Open clip definition",
  "完整动画": "Full animation",
  "原时间轴 {0}–{1} 秒 · 片段时间从 0 开始": "Source timeline {0}–{1} seconds · Clip time starts at 0",
  "Godot / 命名动画片段": "Godot / Named animation clip",
  "填写当前场景的动画片段 UUID，选择后从片段起点播放。clip_id 留空时选择完整动画。仅支持动画片段的场景组装项目生效；更名不影响编号引用。": "Enter an animation clip UUID from the current scene to select and play it from its start. Leave clip_id empty to select the full animation. Requires clip support in an assembled project; renaming preserves ID references.",
  "Godot / 项目动画控制": "Godot / Project animation control",
  "在场景组装项目中控制当前场景的整份动画。command 可选 play、pause、stop、seek；seek 使用 time_seconds 并暂停，play 在末尾重新播放。单场景运行时不控制动画。": "Control the current scene’s full animation in an assembled project. Set command to play, pause, stop or seek. seek uses time_seconds and pauses; play restarts at the end. Single-scene runs leave animation unchanged.",
  "Godot / 事件声音": "Godot / Event audio",
  "填写已声明的音轨 UUID；订阅 sound 后，true 请求播放、false 请求停止。仅当前项目场景访问生效，也可在行为中直接调用声音接口。": "Enter a declared track UUID. Subscribe to sound: true requests play and false requests stop. Applies only to the current project scene visit; audio APIs can also be called directly from behaviors.",
  "声音控制记录": "Audio command history",
  "只读显示实际执行的声音命令，不代表当前播放状态或可听见的声音。切换场景时保留记录，重新运行后清空。": "Read-only history of executed audio commands, not current playback or audible output. History persists across scenes and resets on a new run.",
