  "Godot / 共享状态": "Godot / Shared state",
  "在当前项目运行中累加 visit_count；状态跨场景保留，重新运行后清空。单场景运行时不写入。": "Increment visit_count during the current project run. State persists across scenes and resets on a new run. Single-scene runs do not write state.",
  "Godot / 场景切换": "Godot / Scene switch",
  "在组装运行中请求切换到 target_scene_id 指定的成员场景；请在行为参数中填写目标场景标识。单场景运行时不切换。": "Request a switch to the member scene specified by target_scene_id while running an assembly. Set the destination scene ID in the behavior parameters. Single-scene runs do not switch.",
  "运行对象来自当前场景；访问记录仅记录本次运行，不会切换编辑内容。": "Runtime objects belong to the current scene. This run’s visit history does not change the document being edited.",
