  "定时音轨创建一条播放提示；行为音轨不创建定时提示。候选素材尚未验证；审阅和保存时会核对真实 PCM16 WAV 与资源摘要。": "Timed tracks get one play cue; behavior-triggered tracks get no timed cues. Candidate assets are unverified; review and save check the actual PCM16 WAV and resource digest.",
