  "编辑场景声音": "Edit scene audio",
  "调整已有声音轨道和时间提示。场景、资源与身份保持固定；编辑不会自动播放声音。": "Adjust existing audio tracks and cues. Scene, resource references and identities stay fixed. Editing does not start playback.",
  "声音轨道": "Audio tracks",
  "调整声音轨道，添加或移除时间提示。既有轨道与资源身份保持固定；编辑不会自动播放声音。": "Adjust audio tracks and add or remove timed cues. Existing tracks and resource identities stay fixed. Editing does not start playback.",
