  "调整声音轨道，编排时间提示。既有轨道与资源身份保持固定；编辑不会自动播放声音。": "Adjust audio tracks and arrange timed cues. Existing tracks and resource identities stay fixed. Editing does not start playback.",
  "可为每条提示选择当前音轨。按时间执行；同一时刻按列表顺序执行。上下移动不会改变触发时间。": "Choose a current track for each cue. Cues run by time; cues at the same time run in list order. Moving a cue does not change its time.",
