  "复制或移除声音轨道，编排时间提示。仅复用已有素材，不替换资源；编辑不会自动播放声音。": "Copy or remove audio tracks and arrange timed cues. Reuse existing media without replacing resources. Editing does not start playback.",
  "行为脚本可能通过轨道编号引用声音。移除前请检查脚本；此处不会自动修改脚本。": "Behavior scripts may refer to audio by track ID. Check your scripts before removing tracks; this editor does not update scripts automatically.",
