  "新建脚本": "New script",
  "脚本草稿已准备好。可继续编辑，点击保存后才会登记到工程。": "Your script draft is ready. Continue editing, then click Save to register it in the project.",
  "选择起始内容，在原文编辑器中继续编写，再用保存登记 TXT 脚本。": "Choose a starter, continue writing in the source editor, then use Save to register the TXT script.",
  "本次只创建草稿，不保存、不运行脚本，也不关联场景。起始内容使用 Godot 4 / GDScript，无需先安装 Godot。": "This creates a draft only. It does not save, run the script, or link a scene. Starters use Godot 4 / GDScript; Godot does not need to be installed.",
  "脚本草稿设置": "Script draft settings",
  "起始内容": "Starter",
  "TXT 原文路径": "TXT source path",
  "使用工程正文目录内的 .txt 路径。已有文件会在保存时检查。": "Use a .txt path within the project's document folder. Existing files are checked when saving.",
  "完整脚本预览": "Complete script preview",
  "创建脚本草稿": "Create script draft",
