  "使用参数并在就绪时发出信号；参数和信号映射需在行为文档中设置。": "Use parameters and emit a signal when ready. Configure parameter and signal mappings in the behavior document.",
  "工程或编辑器已变化，设置已保留。请返回编辑器后重新打开。": "The project or editor changed. Your settings are kept. Return to the editor, then reopen this panel.",
  "请审阅完整脚本；创建草稿后可在原文编辑器继续修改。": "Review the complete script. After creating the draft, continue editing in the source editor.",
  "请选择当前工程的文档类型，并填写正文目录内有效的 .txt 路径。": "Choose a document type from this project and enter a valid .txt path within its document folder.",
  "丢弃本次脚本创建设置？编辑器内容不会改变。": "Discard these script creation settings? The editor content will stay unchanged.",
  "正在打开脚本草稿…": "Opening the script draft…",
  "未创建脚本草稿，设置已保留。请检查编辑器状态后重试。": "The script draft was not created. Your settings are kept. Check the editor state and try again.",
  "编辑场景行为": "Edit scene behaviors",
  "编辑当前绑定文档；场景、后端和语言保持固定。脚本须已登记并由本文档引用，不会自动添加关系或执行脚本。": "Edit this binding document. The scene, backend, and language stay fixed. Scripts must already be registered and referenced by this document. No relations are added and no scripts are run.",
  "当前行为绑定": "Current behavior binding",
  "新增行为绑定": "Add binding",
  "移除此绑定": "Remove binding",
  "场景实例": "Scene instance",
  "已关联脚本": "Referenced script",
  "行为参数": "Behavior parameters",
  "参数使用文本、数字或布尔值；名称须为ASCII标识符，具体脚本类型在构建与运行时检查。": "Use text, numbers, or booleans. Names must be ASCII identifiers. Script property types are checked when building and running.",
  "信号映射": "Signal mappings",
  "添加参数": "Add parameter",
  "添加信号映射": "Add signal mapping",
  "最多32条绑定、8份脚本；每条最多32个参数和8个信号。至少保留一条绑定。": "Up to 32 bindings and 8 scripts; each binding supports 32 parameters and 8 signals. Keep at least one binding.",
