  "按住 Shift 或 Ctrl / ⌘ 点击对象可多选，也可以勾选列表。拖动已选对象可整体移动；吸附以拖动的对象为基准，保持间距。": "Shift or Ctrl / ⌘-click objects to select several, or use the list checkboxes. Drag a selected object to move the group; snapping uses the dragged object and preserves spacing.",
