  "同一对象可创建多个独立实例。复制保留配置，位置与覆盖值分别保存；调整顺序会改变重叠时的前后关系。": "Create multiple independent instances of the same object. Copies retain settings; positions and overrides are saved separately. Reordering changes which overlapping instance appears in front.",
