  "方向键按固定步长逐步回放；仅用于本次无头测试，不写入作品文件。": "Replay arrow keys at fixed steps for this headless test. The program is not saved to your work files.",
  "控制步骤（JSON）": "Control steps (JSON)",
  "步长大于 0 且不超过 0.25 秒；1–64 步，总时长不超过 8 秒，最后一步释放全部方向键。每次最多 1024 个对象样本。": "Step duration must be greater than 0 and at most 0.25 seconds; 1–64 steps and at most 8 seconds in total. Release all arrow keys on the final step. Each replay allows at most 1024 object samples.",
