  "控制回放格式有误，请检查步长、步骤和方向键值。": "Invalid control replay. Check the step duration, steps and arrow key values.",
  "控制回放超出对象样本预算，请减少步骤或场景对象。": "Control replay exceeds the object sample budget. Reduce the steps or scene objects.",
