  "恢复会移除共享片段声明并重新读取投影继承；所有引用的局部覆盖仍优先。位置声明必须保留。": "Restore removes shared fragment declarations and reads inherited projection values again. Local overrides still take precedence for every reference. The position declaration must remain.",
  "此片段未启用投影继承，只能移除图片声明；移除后无图，局部图片覆盖仍优先。其他必需声明保持。": "Projection inheritance is disabled for this fragment. Only its image declaration can be removed, leaving no image; local image overrides still take precedence. Other required declarations remain.",
