  "此工程包含运行记录，已保留供你查看。": "This project contains run records and has been preserved for review.",
  "工程目录的位置或身份已变化，已保留供你检查。": "The project directory location or identity changed. It has been preserved for inspection.",
  "自动回收未完成，工程已保留。": "Automatic cleanup did not complete. The project has been preserved.",
  "此工程已不属于当前服务，请刷新列表或重新构建。": "This project is no longer owned by the current service. Refresh the list or rebuild.",
  "工程文件或清单已变化，无法显示为完整工程。请检查保留原因并重新构建。": "Project files or inventories changed, so it cannot be shown as intact. Review the preservation reason and rebuild.",
