  "管理片段定义": "Manage fragment definitions",
  "新增、复制或移除共享片段定义，不创建放置或实例身份。随后可独立编辑演员、组织组和片段放置。": "Add, copy or remove shared fragment definitions without creating placements or instance identities. Edit actors, organizational groups and placements separately afterward.",
