  "复制片段定义": "Copy fragment definition",
  "移除片段定义": "Remove fragment definition",
  "新片段标识": "New fragment ID",
  "片段标识": "Fragment ID",
  "片段标识须在配方内唯一；复制只更换此标识，完整保留原演员和组织组声明。": "The fragment ID must be unique in the recipe. Copying changes only this ID and preserves all actor and organizational group declarations.",
  "初始演员声明": "Initial actor declaration",
  "当前片段原始声明": "Current raw fragment declaration",
  "片段定义影响": "Fragment definition impact",
  "首次放置时检查有效投影和图片内容；本次仅检查声明与已登记依赖，不保证未放置片段的渲染结果。": "Effective projection values and image contents are checked on first placement. This check validates declarations and registered dependencies, and does not guarantee rendering of an unplaced fragment.",
  "检查片段定义修改": "Check definition changes",
  "片段定义修改尚未应用到原文草稿。": "Definition changes have not been applied to the source draft.",
  "丢弃本次片段定义修改？原文草稿不会改变。": "Discard these definition changes? The source draft will remain unchanged.",
  "选择新增、复制或移除后，审阅定义声明及引用影响。": "Choose add, copy or remove, then review the declarations and reference impact.",
  "新增一个未放置片段，包含初始演员且没有组织组；不会生成实例身份。": "Add an unplaced fragment with one initial actor and no organizational groups. No instance identities are generated.",
  "复制完整演员和组织组声明；新片段尚未放置，原片段与所有放置保持。": "Copy all actor and organizational group declarations. The new fragment is unplaced; the original fragment and all placements remain unchanged.",
  "仅移除此未放置片段声明；定义文档、素材、其他片段和全部放置保持。": "Remove only this unplaced fragment declaration. Definition documents, assets, other fragments and all placements remain unchanged.",
  "初始演员输入尚未完整。": "The initial actor input is incomplete.",
