  "原文或预览已变化，请重新预览后管理片段定义。": "The source or preview has changed. Preview the recipe again before managing definitions.",
  "此片段仍被放置引用，须先移除这些放置：{0}": "This fragment is still referenced by placements. Remove these placements first: {0}",
  "引用此定义的放置": "Placement referencing this definition",
  "配方必须保留至少一个片段定义。": "The recipe must retain at least one fragment definition.",
  "片段定义修改有误，请检查标识、声明和数量限制后重试。": "The definition changes are invalid. Check IDs, declarations and count limits, then retry.",
