  "片段定义修改未应用。修改保留，请检查后重试。": "Definition changes were not applied. Your edits are retained; check and retry.",
  "选择一项片段定义操作；一次审阅一个未放置定义的修改。": "Choose a definition operation. Review one unplaced definition change at a time.",
  "片段定义管理暂不可用，请重新预览当前配方后重试。": "Definition management is unavailable. Preview the current recipe again and retry.",
  "片段定义已应用到原文草稿；尚未保存。": "Definition changes applied to the source draft; not saved yet.",
  "片段定义已应用；文本与已保存版本一致。": "Definition changes applied; the text matches the saved version.",
  "新增、复制、重命名或移除共享片段定义，不创建放置或实例身份。重命名同步更新现有放置引用，演员和组织组身份保持。": "Add, copy, rename or remove shared fragment definitions without creating placements or instance identities. Renaming updates existing placement references and keeps actor and group identities.",
  "重命名片段定义": "Rename fragment definition",
  "选择新增、复制、重命名或移除后，审阅定义声明及引用影响。": "Choose add, copy, rename or remove, then review the declarations and reference impact.",
  "重命名片段并同步全部放置引用；演员、组织组身份、有效字段、偏移和局部覆盖保持。不会生成新身份。": "Rename the fragment and update every placement reference. Actor and group identities, effective fields, offsets and local overrides stay unchanged. No new identities are generated.",
