  "当前核心不支持片段重命名；新增、复制和移除仍可使用。": "The current core does not support fragment renaming. Add, copy and remove remain available.",
  "填写配方内唯一的新标识，区分大小写；全部现有放置引用会同步更新，身份与声明保持。": "Enter a new ID unique within this recipe. IDs are case sensitive. All existing placement references will update; identities and declarations stay unchanged.",
  "已放置和未放置片段均可重命名；仅移除操作要求没有放置引用。": "Placed and unplaced fragments can both be renamed. Only removal requires no placement references.",
  "片段标识未变化；请填写不同的新标识后检查。": "The fragment ID is unchanged. Enter a different ID, then check again.",
  "选择一项片段定义操作；一次审阅一个修改。重命名可同步已放置片段的引用。": "Choose a definition operation and review one change at a time. Renaming can update the references of a placed fragment.",
