  "选择对象并勾选要修改的名称或颜色。检查完整候选原文后应用到草稿，再由编辑器普通保存。": "Choose an object and select the name or color to change. Review the complete candidate source, apply it to the draft, then save normally in the editor.",
  "名称保留填写的空格和字符，颜色使用六位十六进制值。对象UUID、变换、未勾选字段和其他对象保持原文。": "Names retain the spaces and characters you enter. Colors use six-digit hexadecimal values. Object UUIDs, transforms, unselected fields and other objects retain their source.",
  "3D属性审阅": "Review 3D properties",
  "检查3D属性": "Check 3D properties",
  "3D属性修改尚未应用到原文草稿。": "3D property changes have not been applied to the source draft.",
  "原文草稿已变化，请关闭后重新打开3D属性编辑。": "The source draft has changed. Close and reopen 3D property editing.",
  "当前核心不支持3D属性编辑，3D只读预览和原文编辑仍可使用。": "The current core does not support 3D property editing. Read-only 3D preview and source editing remain available.",
  "当前核心不支持3D属性编辑": "3D property editing is unavailable in this core",
  "丢弃本次3D属性修改？原文草稿不会改变。": "Discard these 3D property changes? The source draft will remain unchanged.",
  "3D属性未改变，原文草稿保持不变。": "3D properties are unchanged. The source draft remains unchanged.",
  "正在读取3D对象属性…": "Reading 3D object properties…",
  "选择对象并勾选要修改的3D属性。": "Choose an object and select the 3D properties to change.",
  "3D属性已检查，请审阅对象声明与完整原文后应用。": "3D properties checked. Review the object declaration and complete source before applying.",
  "3D属性有误，请检查名称和颜色后重试。": "The 3D properties are invalid. Check the name and color, then retry.",
  "正在应用3D属性到原文草稿…": "Applying 3D properties to the source draft…",
  "3D属性修改未确认应用。修改保留，请核对原文后重试。": "3D property application was not confirmed. Your changes are retained; check the source and retry.",
  "3D属性修改已应用到原文草稿；尚未保存。": "3D property changes applied to the source draft; not saved yet.",
