  "已聚焦当前预览的全部对象；筛选不影响取景，原文保持不变。": "Framed all objects in the current preview. Filtering does not affect framing; source text is unchanged.",
  "无法聚焦全部对象，当前视角与原文保持不变。": "Could not frame all objects. The current view and source text are unchanged.",
  "观察方向": "View direction",
