  "仰视（−Y）": "Bottom (−Y)",
  "按方向查看": "View from direction",
  "标准方向使用透视相机并包住全部对象；拖动沿画面方向旋转，滚轮缩放。仅改变临时视角。": "Standard directions use a perspective camera and frame all objects. Drag to orbit along the screen axes; scroll to zoom. Only the temporary view changes.",
  "已按所选方向查看全部对象；选择、筛选和原文保持不变。": "Showing all objects from the chosen direction. Selection, filtering and source text are unchanged.",
  "无法切换观察方向，当前视角与原文保持不变。": "Could not change the view direction. The current view and source text are unchanged.",
  "拖动方式": "Drag action",
  "旋转视角": "Orbit view",
  "平移视角": "Pan view",
  "标准方向使用透视相机并包住全部对象；视角操作仅影响预览，不修改原文。": "Standard directions use a perspective camera and frame all objects. View controls affect only the preview, leaving source text unchanged.",
  "旋转模式下单击选择、双击聚焦。平移模式、Shift+拖动或鼠标中键只移动视角，不选择对象；滚轮缩放。": "In orbit mode, click to select and double-click to focus. Pan mode, Shift-drag or the middle mouse button moves the view without selecting objects; scroll to zoom.",
  "旋转模式下单击选择、双击聚焦。平移模式、Shift+拖动或鼠标中键只移动视角，不选择对象；滚轮缩放。双指拖动平移，捏合缩放；松开任一手指结束。": "In orbit mode, click to select and double-click to focus. Pan mode, Shift-drag or the middle mouse button moves the view without selecting objects; scroll to zoom. Two fingers pan and pinch to zoom; lifting either finger ends the gesture.",
  "当前渲染器不支持切换拖动方式。": "This renderer does not support switching the drag action.",
  "已切换为平移视角；拖动仅移动临时镜头。": "Pan mode selected. Dragging moves only the temporary camera.",
  "已切换为旋转视角；单击选择，拖动旋转。": "Orbit mode selected. Click to select; drag to orbit.",
  "无法切换拖动方式，当前视图与原文保持不变。": "Could not change the drag action. The current view and source text are unchanged.",
  "视图投影": "View projection",
