  "已切换为透视观察；仅影响预览，不修改作者相机。": "Perspective view selected. Only the preview changes; the authored camera is unchanged.",
  "无法切换投影方式，当前视图与原文保持不变。": "Could not change the projection. The current view and source text are unchanged.",
  "当前渲染器不支持切换投影方式。": "This renderer does not support switching projections.",
  "只读预览当前JSON草稿；所有视图操作都不修改原文。": "Read-only preview of the current JSON draft. View controls never change the source.",
  "标准方向会包住全部对象。透视显示远近；正交方便比较布局。": "Standard directions frame all objects. Perspective shows depth; orthographic helps compare layouts.",
