  "随机种子": "Random seed",
  "逐项勾选要修改的背景、相机、光照、雾或粒子。检查完整候选原文后应用到草稿，再由编辑器普通保存。": "Select the background, camera, light, fog or particle fields to change. Review the complete proposed source, apply it to the draft, then save in the editor.",
  "粒子在范围内循环移动。调整尺寸与速度可表现雨雪；数量设为0关闭，尺寸不能超过对应范围。": "Particles repeat within the volume. Adjust size and velocity for rain or snow. Set count to 0 to disable; size must fit within each extent.",
  "当前核心不支持粒子场编辑，其他环境字段仍可修改。": "This core does not support particle field editing. Other environment fields remain editable.",
  "3D环境有误，请检查颜色、相机、光照、雾和粒子范围后重试。": "Invalid 3D environment. Check the color, camera, lighting, fog and particle ranges, then retry.",
  "当前渲染器不支持粒子场，请重新打开预览或更新应用。": "This renderer does not support particle fields. Reopen the preview or update the app.",
