  "本次声明使用 Godot 4 / GDScript；创建不要求已安装 Godot。保存后可在行为编辑器中添加参数、信号和更多绑定。": "This declaration uses Godot 4 / GDScript. Godot need not be installed to create it. After saving, use the behavior editor to add parameters, signals, and more bindings.",
