  "场景动画片段已变化，请重新读取；参数与审阅保持不变。": "Scene animation clips changed. Reload them; parameters and review are unchanged.",
  "动画片段使用位置": "Animation clip usage",
  "读取动画片段使用位置": "Read animation clip usage",
  "当前表单片段：{0} · {1}": "Clip in the current form: {0} · {1}",
  "片段来自当前表单；文字匹配来自上次读取的同场景已保存行为。只匹配完整片段编号，不解析脚本、其他场景或未保存行为草稿；未发现匹配不代表可以安全移除。": "Clips reflect the current form. Text matches reflect the last read of saved behaviors in this scene. Only complete clip IDs are matched; scripts, other scenes, and unsaved behavior drafts are not scanned. No matches does not mean a clip is safe to remove.",
  "正在读取已保存行为中的动画片段文字匹配…": "Reading animation clip text matches in saved behaviors…",
  "Godot / 事件动画片段": "Godot / Event animation clip",
  "订阅 event_name（默认 checkpoint）；收到事件后从头播放 clip_id 指定的片段，留空则播放完整动画。仅支持片段的项目运行生效；就绪时不发布事件，退出时取消订阅。": "Subscribe to event_name (checkpoint by default). Each event plays clip_id from the start; leave it empty for the full animation. Requires clip support in project runs. It publishes no event on ready and unsubscribes on exit.",

  "动画状态快照": "Animation state snapshots",
  "在切换场景或运行结束前采集脚本状态；强制取消可能没有记录。这里只显示脚本已接受状态，不表示动画命令已经执行，也不重建中间转换。": "Script state is captured before a scene switch or run exit; forced cancellation may leave no record. This view shows states accepted by scripts, not executed animation commands, and does not reconstruct intermediate transitions.",
  "按场景、行为绑定、脚本或状态筛选": "Filter by scene, behavior binding, script, or state",
