  "没有匹配的动画状态快照。": "No matching animation state snapshots.",
  "尚未采集动画状态快照。": "No animation state snapshot has been captured yet.",
  "动画状态脚本的片段参数必须是空字符串或小写 UUID，请检查行为绑定。": "Animation state script clip parameters must be empty strings or lowercase UUIDs. Check the behavior binding.",
  "动画状态进入记录": "Animation state entry records",
  "记录脚本每次接受进入状态，包括初始进入和同状态重启；重复记录独立保留。不推测触发原因，也不表示动画命令已经执行。强制取消可能留下不完整记录。": "Records each state entry accepted by the script, including initial entry and restarting the same state. Repeated entries are kept separately. These records do not infer triggers or confirm animation command execution. Forced cancellation may leave incomplete records.",
  "脚本接受进入状态：{0}": "State entry accepted by script: {0}",
  "进入记录 {0} · 第 {1} 次访问 · 场景 {2} · 场景时间 {3} 秒": "Entry {0} · Visit {1} · Scene {2} · Scene time {3} s",
  "进入时已执行动画命令序号：{0}": "Last executed animation command sequence at entry: {0}",
  "进入序号 {0} · 显示 {1} / {2} 条记录": "Entry sequence {0} · Showing {1} / {2} records",
  "没有匹配的动画状态进入记录。": "No matching animation state entry records.",
  "尚未采集动画状态进入记录。": "No animation state entry has been captured yet.",
  "正在打开动画状态进入来源…": "Opening animation state entry source…",
  "无法打开动画状态进入来源，请返回编辑器查找该文档。": "Could not open the animation state entry source. Return to the editor to find the document.",
  "动画状态进入记录与构建时的控制器身份或状态不一致，运行已停止。": "An animation state entry differs from the controller identity or state captured at build time. The run has stopped.",
  "动画状态进入记录超出本次运行的 128 条限制，运行已停止；请减少重复进入或拆分测试。": "Animation state entries exceeded the limit of 128 per run, so the run has stopped. Reduce repeated entries or split the test.",
  "控制器状态回看": "Controller state review",
  "关闭回看": "Close review",
  "回看此控制器": "Review this controller",
  "仅回看此控制器本次场景访问的完整进入顺序，不受记录列表筛选影响；这里不会跳转运行时间或改变播放。": "Review the complete entry order for this controller during this scene visit. The record list filter does not affect this view. Reviewing does not seek runtime time or change playback.",
  "选择进入记录": "Choose an entry record",
  "上一条进入记录": "Previous entry",
  "下一条进入记录": "Next entry",
  "该记录之后的同绑定已执行命令": "Executed commands from the same binding after this record",
  "按进入时的已执行命令序号截取同一次访问、同一绑定的后续记录。多次进入可以共享这些结果；它们不一定由所选进入触发。": "Shows later records from the same visit and binding after the executed command sequence at entry. Several entries can share these results; the selected entry did not necessarily trigger them.",
