  "进入来源：直接进入（无事件或完成回调上下文）": "Entry source: direct entry (outside an event or completion callback)",
  "记录脚本每次接受进入状态及当时的回调来源。重复记录独立保留；不包含分支命中或条件求值过程，也不表示动画命令已经执行。强制取消可能留下不完整记录。": "Records every state entry accepted by the script and its callback source. Repeated entries are kept separately. These records do not trace selected branches or condition evaluation, or confirm animation command execution. Forced cancellation may leave incomplete records.",
  "关联事件：{0}": "Related event: {0}",
  "完成片段：{0} · {1}": "Completed clip: {0} · {1}",
  "完成对象：完整动画": "Completed selection: full animation",
  "事件值：{0}": "Event value: {0}",
  "进入已记录；此订阅的回调结果尚未确认。": "Entry recorded; the callback result for this subscription is not yet confirmed.",
  "此订阅的同步回调已成功返回；后续动画命令仍需查看执行记录。": "This subscription’s synchronous callback returned successfully; check executed command records for subsequent animation commands.",
  "来源记录说明进入发生在哪个回调中；不包含分支命中或条件求值过程。": "The source identifies the callback during which entry occurred; it does not trace selected branches or condition evaluation.",
  "事件投递回看": "Event delivery review",
  "关闭事件回看": "Close event review",
  "查看所选事件的发布与各订阅投递记录，不受事件列表筛选影响。这里不会发布事件或改变运行。": "Review the selected event and its subscription deliveries independently of the event list filter. This view does not publish events or change execution.",
  "选择事件记录": "Choose an event record",
  "订阅投递与动画进入": "Subscription deliveries and animation entries",
  "正在打开关联控制器…": "Opening related controller…",
