  "事件 {0} · {1}": "Event {0} · {1}",
  "事件 {0} · 第 {1} 次访问 · 场景 {2}": "Event {0} · Visit {1} · Scene {2}",
  "发布来源：{0} · {1}": "Publisher source: {0} · {1}",
  "仅关联本事件和本订阅确证的动画进入。未采集进入记录不能说明条件失败或行为没有执行；回调成功也不保证后续动画命令已执行。": "Only confirmed animation entries from this event and subscription are linked. Missing entry records do not establish a failed condition or an unexecuted behavior; a successful callback does not guarantee later animation commands executed.",
  "此运行协议未记录动画进入来源，无法关联；事件及投递记录仍可查看。": "This runtime protocol did not record animation entry sources, so links are unavailable. Event and delivery records remain available.",
  "订阅 {0} · {1}": "Subscription {0} · {1}",
  "订阅来源：{0} · {1}": "Subscriber source: {0} · {1}",
