  "回看此事件": "Review this event",
  "缺失（不提供此键）": "Missing (omit this key)",
  "手动样本值": "Manual sample value",
  "收起事件试算": "Collapse event trial",
  "事件试算": "Event trial",
  "使用手动样本检查当前表的事件分支与条件，不执行脚本、不发布事件，也不代表历史运行或动画播放成功。": "Check this table’s event branches and conditions using manual samples. This does not execute scripts or publish events, and does not represent past execution or successful animation playback.",
  "样本当前状态": "Sample current state",
  "样本事件名称": "Sample event name",
  "手动共享状态样本": "Manual shared-state samples",
  "仅列出当前状态与事件涉及的共享键。同一键在本次试算中使用固定值；实际运行可能在每次读取时变化。": "Only shared keys used by this state and event are listed. Each key has a fixed value for this trial; actual execution may read a different value each time.",
  "此状态与事件没有需要提供的共享状态键。": "This state and event require no shared-state keys.",
  "试算此事件": "Try this event",
  "手动试算结果": "Manual trial result",
  "样本事件载荷类型": "Sample event payload type",
  "共享状态样本：{0}": "Shared-state sample: {0}",
  "当前核心无法比较事件样本；状态表输入仍然保留。": "This core cannot compare event samples. State-table inputs are retained.",
  "请选择当前表中的状态。": "Choose a state from the current table.",
  "请输入有效事件名称；未配置的合法名称也可以试算。": "Enter a valid event name. Valid names absent from the table can also be tried.",
  "请检查手动样本：数字须为有限十进制且绝对值不超过 1e9，字符串须为有效 Unicode 且不超过 4096 UTF-8 字节。": "Check the manual samples: numbers must be finite decimal values with an absolute value at most 1e9; strings must be valid Unicode with at most 4096 UTF-8 bytes.",
