  "共享键缺失，条件不匹配（包括不等于比较）。": "The shared key is missing, so the condition does not match (including not-equal comparisons).",
  "样本类型不同，条件不匹配（包括不等于比较）。": "The sample type differs, so the condition does not match (including not-equal comparisons).",
  "比较匹配。": "The comparison matches.",
  "比较不匹配。": "The comparison does not match.",
  "当前核心无法提供事件试算。": "This core cannot provide event trials.",
  "表单当前不可操作，试算结果已清除。": "The form is currently unavailable. Trial results have been cleared.",
  "已移除状态：{0}": "Removed state: {0}",
  "状态表尚未有效，无法试算。请先修正状态、转换和条件字段。": "The state table is not yet valid. Correct its state, transition and condition fields before trying an event.",
  "无法试算此样本，请检查输入。": "Could not evaluate this sample. Check the inputs.",
  "收起状态试算": "Collapse state trial",
  "状态试算": "State trial",
  "使用手动样本检查状态转换；试算不会推进状态，记录并继续才采用预测目标。这里不执行脚本、不发布事件，也不代表历史运行或动画播放成功。": "Check state transitions with manual samples. A trial does not advance the state; Record and continue adopts the predicted target. This does not run scripts or publish events, and does not represent past execution or successful animation playback.",
  "样本触发方式": "Sample trigger",
  "项目事件样本": "Project event sample",
  "当前动画完成（手动假设）": "Current animation completed (manual assumption)",
  "假设控制器有效，且当前所选片段的完成通知已送达。这里只检查完成转换，不模拟片段匹配、播放器或进入成功。": "Assume the controller is active and a completion notification for the selected clip has arrived. Only the completion transition is checked; clip matching, the player and successful entry are not simulated.",
  "试算完成转换": "Try completion transition",
  "记录并继续": "Record and continue",
  "撤回最后一步": "Undo last step",
  "清空步骤": "Clear steps",
  "手动步骤历史": "Manual step history",
  "{0}/{1} 步 · 样本 {2}/{3} 字节；仅保留本次表单会话。": "{0}/{1} steps · {2}/{3} sample bytes; retained only for this form session.",
  "手动步骤 {0}：{1} → {2}": "Manual step {0}: {1} → {2}",
  "事件样本：{0} · {1}": "Event sample: {0} · {1}",
  "假设当前动画完成通知已送达。": "Assume the current animation completion notification arrived.",
  "已提供的共享样本：{0}": "Provided shared samples: {0}",
  "无（其余键缺失）": "None (other keys are missing)",
  "此步未读取事件载荷或共享样本。": "This step did not read an event payload or shared samples.",
  "查看此步条件详情": "View conditions for this step",
  "此步没有候选转换。": "This step has no candidate transition.",
  "动画完成转换": "Animation completion transition",
  "手动选择了起始状态；此前步骤已清除。": "A starting state was selected manually; previous steps were cleared.",
  "步骤或样本预算已满，请撤回或清空步骤后继续。": "The step or sample budget is full. Undo or clear steps to continue.",
  "已记录此手动步骤；可填写下一样本。": "This manual step was recorded. Enter the next sample.",
  "已撤回最后一步并恢复当时的手动样本。": "The last step was undone and its original manual sample restored.",
  "步骤已清空；当前手动状态与输入保持不变。": "Steps were cleared. The current manual state and inputs are unchanged.",
  "用于撤回的原始输入超过 256 KiB 预算；请缩短输入或撤回、清空步骤。单次试算仍可使用。": "Raw inputs retained for undo exceed the 256 KiB budget. Shorten inputs, undo or clear steps. Single trials remain available.",
  "试算用例": "Trial case",
  "将已记录路径导出为手动预期；导入后明确在当前表上重跑。只比较每步目标状态和是否发生转换，不区分通往同一目标的分支，也不证明动画实际运行成功。": "Export recorded steps as manual expectations, then explicitly replay an imported case against the current table. Checks compare each target state and whether a transition occurs; branches with the same target are not distinguished. This does not prove successful animation execution.",
  "导出当前路径 JSON": "Export current path JSON",
